-- ============================================================
-- TABLE: quotes
-- Stores daily quotes of Sathya Sai Baba and Maha Periyava
-- ============================================================
CREATE TABLE IF NOT EXISTS public.quotes (
  id            BIGSERIAL PRIMARY KEY,
  guru          TEXT NOT NULL, -- 'sai' or 'periyava'
  quote_english TEXT NOT NULL,
  quote_tamil   TEXT NOT NULL,
  created_at    TIMESTAMPTZ DEFAULT NOW()
);

-- RLS Configuration
ALTER TABLE public.quotes ENABLE ROW LEVEL SECURITY;

-- Select policy: public read
CREATE POLICY "Public read quotes" ON public.quotes
  FOR SELECT USING (true);

-- Insert policy: anyone can insert
CREATE POLICY "Anyone can manage quotes" ON public.quotes
  FOR ALL USING (true) WITH CHECK (true);

